package com.ryanjei.orushio.pve.paper;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import java.util.UUID;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;
class SetupAdministratorOwnershipTest{@TempDir Path temp;
 @Test void 新規Orushio付与は再起動後も解除可能で解除も永続化する(){UUID id=UUID.randomUUID();var first=new SetupAdministratorOwnership(temp.resolve("data"),temp);first.add(id);assertTrue(new SetupAdministratorOwnership(temp.resolve("data"),temp).contains(id));first.remove(id);assertFalse(new SetupAdministratorOwnership(temp.resolve("data"),temp).contains(id));}
 @Test void 旧Orushio付与が一意に識別できる場合だけmigrationする()throws Exception{UUID id=UUID.randomUUID();Path data=temp.resolve("data"),logs=data.resolve("logs");Files.createDirectories(logs);Files.writeString(logs.resolve("audit-legacy.jsonl"),"{\"code\":\"SETUP_ADMINISTRATOR_GRANTED\"}\n");Files.writeString(temp.resolve("ops.json"),"[{\"uuid\":\""+id+"\"}]");var migrated=new SetupAdministratorOwnership(data,temp);assertTrue(migrated.contains(id));assertTrue(new SetupAdministratorOwnership(data,temp).contains(id));}
 @Test void 元からのOPや曖昧な複数OPを所有扱いしない()throws Exception{UUID manual=UUID.randomUUID();Path manualRoot=temp.resolve("manual"),manualData=manualRoot.resolve("data");Files.createDirectories(manualRoot);Files.writeString(manualRoot.resolve("ops.json"),"[{\"uuid\":\""+manual+"\"}]");assertFalse(new SetupAdministratorOwnership(manualData,manualRoot).contains(manual));Path ambiguous=temp.resolve("ambiguous"),logs=ambiguous.resolve("data/logs");Files.createDirectories(logs);Files.writeString(logs.resolve("audit.jsonl"),"{\"code\":\"SETUP_ADMINISTRATOR_GRANTED\"}\n");Files.writeString(ambiguous.resolve("ops.json"),"[{\"uuid\":\""+manual+"\"},{\"uuid\":\""+UUID.randomUUID()+"\"}]");assertFalse(new SetupAdministratorOwnership(ambiguous.resolve("data"),ambiguous).contains(manual));}
}
